
(function(){
  'use strict';

  /* Carômetro da 7ª CRE — nomes vinculados exatamente ao banco estrutural. */
  try{
    if(typeof GEO_AGENT_PHOTOS!=='undefined' && typeof GEO_AGENT_PHOTO_POS!=='undefined'){
      GEO_AGENT_PHOTOS["Ana Cristina Barros Araújo"]="data:image/jpeg;base64,";
      GEO_AGENT_PHOTO_POS["Ana Cristina Barros Araújo"]='50% 42%';
      GEO_AGENT_PHOTOS["Ana Patricia Neves Pinheiro"]="data:image/jpeg;base64,";
      GEO_AGENT_PHOTO_POS["Ana Patricia Neves Pinheiro"]='50% 42%';
      GEO_AGENT_PHOTOS["Chrystiane Rodrigues Machado de Carvalho"]="data:image/jpeg;base64,";
      GEO_AGENT_PHOTO_POS["Chrystiane Rodrigues Machado de Carvalho"]='50% 42%';
      GEO_AGENT_PHOTOS["Gabriela Gonçalves Ozório"]="data:image/jpeg;base64,";
      GEO_AGENT_PHOTO_POS["Gabriela Gonçalves Ozório"]='50% 42%';
      GEO_AGENT_PHOTOS["Fabricia Belo Viana"]="data:image/jpeg;base64,";
      GEO_AGENT_PHOTO_POS["Fabricia Belo Viana"]='50% 42%';
      GEO_AGENT_PHOTOS["Isadora Araújo do Nascimento"]="data:image/jpeg;base64,";
      GEO_AGENT_PHOTO_POS["Isadora Araújo do Nascimento"]='50% 42%';
      GEO_AGENT_PHOTOS["Ivani Alves Rodrigues"]="data:image/jpeg;base64,";
      GEO_AGENT_PHOTO_POS["Ivani Alves Rodrigues"]='50% 42%';
      GEO_AGENT_PHOTOS["Lilian Dias"]="data:image/jpeg;base64,";
      GEO_AGENT_PHOTO_POS["Lilian Dias"]='50% 42%';
      GEO_AGENT_PHOTOS["Michele Cristina Mello Teodosio Montenari"]="data:image/jpeg;base64,";
      GEO_AGENT_PHOTO_POS["Michele Cristina Mello Teodosio Montenari"]='50% 42%';
      GEO_AGENT_PHOTOS["Renata Chagas Teixeira da Silva de Azeredo"]="data:image/jpeg;base64,";
      GEO_AGENT_PHOTO_POS["Renata Chagas Teixeira da Silva de Azeredo"]='50% 42%';
      GEO_AGENT_PHOTOS["Renata Da Silva Seixas"]="data:image/jpeg;base64,";
      GEO_AGENT_PHOTO_POS["Renata Da Silva Seixas"]='50% 42%';
      GEO_AGENT_PHOTOS["Renata Rosas de Almeida"]="data:image/jpeg;base64,";
      GEO_AGENT_PHOTO_POS["Renata Rosas de Almeida"]='50% 42%';
      GEO_AGENT_PHOTOS["Silvia Rocha da Costa"]="data:image/jpeg;base64,";
      GEO_AGENT_PHOTO_POS["Silvia Rocha da Costa"]='50% 42%';
    }
  }catch(err){console.warn('v181: falha ao aplicar carômetro da 7ª CRE',err);}

  const byId=id=>document.getElementById(id);
  const isIdeb=()=>byId('somModalidade')?.value==='IDEB 2025';
  const scope=()=>Number(byId('regionalScopeSelect')?.value||0);
  const mode=()=>byId('somMode')?.value||'individual';
  const metric=()=>byId('somMetric')?.value||'ideb2025';
  const segment=()=>byId('somAnoEscolar')?.value||'';
  const fmt=v=>Number(v).toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1});
  const fmtDelta=v=>`${Number(v)>0?'+':''}${Number(v).toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1})}`;
  const rowCreNum=row=>{
    const raw=String(row?.cre||row?.regional||row?.creLabel||'');
    const m=raw.match(/\d{1,2}/);return m?Number(m[0]):0;
  };
  const creLabel=n=>`CRE ${String(n).padStart(2,'0')}`;
  const specificAgent=()=>{
    const val=byId('somAgente')?.value||'';
    return typeof somIsSpecificAgent==='function'?somIsSpecificAgent(val):Boolean(val);
  };
  const hasDetail=()=>Boolean(String(byId('somSearch')?.value||'').trim())||specificAgent()||byId('somPriority')?.value==='sim';
  const pureSme=()=>isIdeb()&&scope()===0&&!hasDetail();
  const progressActive=()=>pureSme()&&(mode()==='progressao'||metric()==='crescimento');
  const colorPalette=['#0e5a91','#1d8f68','#d9861c','#7b61a8','#2f7f8f','#b45757','#4c74b8','#8a6d3b','#277a6b','#9a5f91','#5c7082'];

  function currentIdebRows() {
    const rows=typeof somFilteredRows==='function'?somFilteredRows({ignoreEdicao:true,ignoreSearch:true}):[];
    return (rows||[]).filter(row=>row&&row.modalidade==='IDEB 2025');
  }
  function groupCres(rows,key) {
    const map=new Map();
    (rows||[]).forEach(row=>{
      const n=rowCreNum(row);if(!n)return;
      if(!map.has(n))map.set(n,[]);
      map.get(n).push(row);
    });
    return [...map.entries()].map(([n,rs])=>{
      const aggregate=rs.filter(r=>r?._afCreAggregate);
      const source=aggregate.length?aggregate:rs;
      const value=typeof somAvg==='function'?somAvg(source,key):null;
      const schools=new Set(rs.filter(r=>r?.escola&&!r?._afCreAggregate).map(r=>String(r.codigoSME||r.codigoINEP||`${n}|${r.escola}`)));
      return {n,label:creLabel(n),value:Number(value),count:schools.size||source.length};
    }).filter(item=>Number.isFinite(item.value)).sort((a,b)=>a.n-b.n);
  }
  function scaleBounds(values,pad=.35) {
    const lo=Math.min(...values),hi=Math.max(...values);
    let min=Math.max(0,Math.floor((lo-pad)*10)/10),max=Math.ceil((hi+pad)*10)/10;
    if(max-min<1){const mid=(min+max)/2;min=Math.max(0,Math.floor((mid-.55)*10)/10);max=Math.ceil((mid+.55)*10)/10;}
    return {min,max};
  }
  function renderCreBars(rows) {
    const chart=byId('somCreChart'),card=byId('somCreCompareCard');if(!chart||!card)return false;
    const key=metric()==='ideb2023'?'ideb2023':'ideb2025';
    const data=groupCres(rows,key);
    if(data.length<2)return false;
    card.classList.add('v181-cre-overview');chart.classList.add('v181-cre-bars');
    const title=byId('somCreTitle'),subtitle=byId('somCreSubtitle');
    if(title)title.textContent=`IDEB das CREs — ${key==='ideb2023'?'2023':'2025'}`;
    if(subtitle)subtitle.textContent=`Toda a SME · ${segment()||'segmento selecionado'} · escala vertical ajustada ao intervalo dos resultados.`;
    const values=data.map(d=>d.value),{min,max}=scaleBounds(values,.28);
    const w=1120,h=430,pL=58,pR=24,pT=40,pB=92,plotW=w-pL-pR,plotH=h-pT-pB;
    const y=v=>pT+plotH*(1-(v-min)/(max-min||1));
    const slot=plotW/data.length,bw=Math.min(62,slot*.58);
    const ticks=Array.from({length:6},(_,i)=>min+(max-min)*i/5);
    const grid=ticks.map(v=>`<g><line x1="${pL}" y1="${y(v)}" x2="${w-pR}" y2="${y(v)}" stroke="#e1ebf2" stroke-width="1"/><text x="${pL-10}" y="${y(v)+4}" text-anchor="end" fill="#718597" font-size="11">${fmt(v)}</text></g>`).join('');
    const bars=data.map((d,i)=>{
      const cx=pL+slot*(i+.5),top=y(d.value),base=y(min),height=Math.max(2,base-top);
      return `<g class="v181-cre-bar"><rect x="${cx-bw/2}" y="${top}" width="${bw}" height="${height}" rx="8" fill="#1c79b8"><title>${d.label} · IDEB ${fmt(d.value)} · ${d.count} escolas válidas</title></rect><text x="${cx}" y="${top-10}" text-anchor="middle" fill="#12385d" font-size="14" font-weight="900">${fmt(d.value)}</text><text x="${cx}" y="${h-pB+26}" transform="rotate(-28 ${cx} ${h-pB+26})" text-anchor="end" fill="#526779" font-size="12" font-weight="800">${d.label}</text></g>`;
    }).join('');
    chart.innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="IDEB das CREs no segmento selecionado">${grid}<line x1="${pL}" y1="${y(min)}" x2="${w-pR}" y2="${y(min)}" stroke="#b9ccd9" stroke-width="1.3"/>${bars}</svg>`;
    return true;
  }

  const previousCreChart=window.renderSomCreChart;
  window.renderSomCreChart=function(){
    if(pureSme()&&!progressActive()&&['ideb2023','ideb2025'].includes(metric())){
      const card=byId('somCreCompareCard');if(card)card.style.display='block';
      if(renderCreBars(currentIdebRows()))return;
    }
    const chart=byId('somCreChart'),card=byId('somCreCompareCard');
    chart?.classList.remove('v181-cre-bars');card?.classList.remove('v181-cre-overview');
    return typeof previousCreChart==='function'?previousCreChart():undefined;
  };

  function adjustedLabels(values,y,minY,maxY,gap=17) {
    const items=values.map((value,index)=>({index,raw:y(value),y:y(value)})).sort((a,b)=>a.raw-b.raw);
    for(let i=1;i<items.length;i++)items[i].y=Math.max(items[i].raw,items[i-1].y+gap);
    if(items.length&&items.at(-1).y>maxY){
      const shift=items.at(-1).y-maxY;items.forEach(item=>item.y-=shift);
      for(let i=items.length-2;i>=0;i--)items[i].y=Math.min(items[i].y,items[i+1].y-gap);
    }
    if(items.length&&items[0].y<minY){
      const shift=minY-items[0].y;items.forEach(item=>item.y+=shift);
    }
    const result=[];items.forEach(item=>result[item.index]=item.y);return result;
  }
  function renderCreProgress() {
    const card=byId('somProgressCard'),chart=byId('somProgressChart'),tableTarget=byId('somProgressTable');if(!card||!chart)return;
    card.classList.add('open');chart.classList.add('v181-cre-progress');
    const title=card.querySelector('.panel-title h3'),subtitle=card.querySelector('.panel-title p');
    if(title)title.textContent='Progressão das CREs — IDEB 2023 → 2025';
    if(subtitle)subtitle.textContent=`Toda a SME · ${segment()||'segmento selecionado'}. Cada linha representa uma CRE; clique na legenda para destacar sua trajetória.`;
    const rows=currentIdebRows(),map=new Map();
    rows.forEach(row=>{const n=rowCreNum(row);if(!n)return;if(!map.has(n))map.set(n,[]);map.get(n).push(row);});
    const series=[...map.entries()].map(([n,rs])=>{
      // v209 — evolução agregada usa exatamente o mesmo universo de escolas em 2023 e 2025.
      // Resultados sem uma das duas edições ficam fora apenas da evolução; continuam válidos
      // nas fotografias isoladas de IDEB 2023 ou IDEB 2025.
      const paired=rs.filter(r=>{
        if(r?._afCreAggregate||!r?.escola)return false;
        const raw23=r.ideb2023,raw25=r.ideb2025;
        if(raw23===null||raw23===undefined||String(raw23).trim()==='')return false;
        if(raw25===null||raw25===undefined||String(raw25).trim()==='')return false;
        return Number.isFinite(Number(raw23))&&Number.isFinite(Number(raw25));
      });
      if(!paired.length)return null;
      const v23=paired.reduce((sum,r)=>sum+Number(r.ideb2023),0)/paired.length;
      const v25=paired.reduce((sum,r)=>sum+Number(r.ideb2025),0)/paired.length;
      return {n,label:creLabel(n),v23,v25,delta:v25-v23,pairedCount:paired.length};
    }).filter(item=>item&&Number.isFinite(item.v23)&&Number.isFinite(item.v25)).sort((a,b)=>a.n-b.n);
    if(series.length<2){
      chart.innerHTML='<div class="som-empty">Não há pelo menos duas CREs com IDEB válido em 2023 e 2025 neste recorte.</div>';
      if(tableTarget)tableTarget.innerHTML='';return;
    }
    const values=series.flatMap(s=>[s.v23,s.v25]),{min,max}=scaleBounds(values,.28);
    const w=1120,h=440,pL=120,pR=120,pT=34,pB=62,plotH=h-pT-pB,x23=205,x25=w-205;
    const y=v=>pT+plotH*(1-(v-min)/(max-min||1));
    const leftY=adjustedLabels(series.map(s=>s.v23),y,pT+5,h-pB-5,18);
    const rightY=adjustedLabels(series.map(s=>s.v25),y,pT+5,h-pB-5,18);
    const ticks=Array.from({length:6},(_,i)=>min+(max-min)*i/5);
    const grid=ticks.map(v=>`<g><line x1="${x23}" y1="${y(v)}" x2="${x25}" y2="${y(v)}" stroke="#e4edf3" stroke-width="1"/><text x="${w/2}" y="${y(v)-4}" text-anchor="middle" fill="#9aabba" font-size="9">${fmt(v)}</text></g>`).join('');
    const groups=series.map((s,i)=>{
      const color=colorPalette[i%colorPalette.length],y23=y(s.v23),y25=y(s.v25),ly=leftY[i],ry=rightY[i];
      return `<g class="v181-cre-series" data-cre-idx="${i}" style="opacity:.78"><line x1="${x23}" y1="${y23}" x2="${x25}" y2="${y25}" stroke="${color}" stroke-width="3.2" stroke-linecap="round"/><circle cx="${x23}" cy="${y23}" r="5" fill="${color}" stroke="#fff" stroke-width="1.5"/><circle cx="${x25}" cy="${y25}" r="5" fill="${color}" stroke="#fff" stroke-width="1.5"/><line x1="${x23-6}" y1="${y23}" x2="${x23-30}" y2="${ly}" stroke="${color}" stroke-width="1" opacity=".65"/><text x="${x23-38}" y="${ly+4}" text-anchor="end" fill="${color}" font-size="12" font-weight="900">${fmt(s.v23)}</text><line x1="${x25+6}" y1="${y25}" x2="${x25+30}" y2="${ry}" stroke="${color}" stroke-width="1" opacity=".65"/><text x="${x25+38}" y="${ry+4}" text-anchor="start" fill="${color}" font-size="12" font-weight="900">${fmt(s.v25)}</text><title>${s.label} · ${fmt(s.v23)} → ${fmt(s.v25)} · ${fmtDelta(s.delta)}</title></g>`;
    }).join('');
    const legend=series.map((s,i)=>`<button type="button" data-cre-legend="${i}" aria-pressed="false"><i style="background:${colorPalette[i%colorPalette.length]}"></i>${s.label}</button>`).join('');
    chart.innerHTML=`<div class="v181-progress-summary"><span><strong>${series.length} CREs</strong> com resultados pareados no recorte.</span><span>Valores de 2023 à esquerda e 2025 à direita.</span></div><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Progressão do IDEB das CREs entre 2023 e 2025">${grid}<text x="${x23}" y="${h-18}" text-anchor="middle" fill="#526779" font-size="14" font-weight="900">IDEB 2023</text><text x="${x25}" y="${h-18}" text-anchor="middle" fill="#526779" font-size="14" font-weight="900">IDEB 2025</text>${groups}</svg><div class="v181-cre-legend"><button type="button" data-cre-reset>Mostrar todas</button>${legend}</div>`;
    let active=null;
    const apply=index=>{
      active=(index===null||active===index)?null:index;
      chart.querySelectorAll('.v181-cre-series').forEach(el=>{
        const selected=active!==null&&Number(el.dataset.creIdx)===active;
        el.style.opacity=active===null?'.78':(selected?'1':'.07');
        el.style.filter=selected?'drop-shadow(0 5px 8px rgba(18,56,93,.22))':'none';
        el.querySelector('line')?.setAttribute('stroke-width',selected?'5':'3.2');
      });
      chart.querySelectorAll('[data-cre-legend]').forEach(btn=>{
        const selected=active!==null&&Number(btn.dataset.creLegend)===active;
        btn.classList.toggle('active',selected);btn.setAttribute('aria-pressed',String(selected));
      });
    };
    chart.querySelectorAll('[data-cre-legend]').forEach(btn=>btn.addEventListener('click',()=>apply(Number(btn.dataset.creLegend))));
    chart.querySelectorAll('.v181-cre-series').forEach(el=>el.addEventListener('click',()=>apply(Number(el.dataset.creIdx))));
    chart.querySelector('[data-cre-reset]')?.addEventListener('click',()=>{active=null;apply(null);});
    if(tableTarget&&typeof table==='function'){
      table('somProgressTable',series.map(s=>({cre:s.label,ideb2023:fmt(s.v23),ideb2025:fmt(s.v25),crescimento:fmtDelta(s.delta)})),[['cre','CRE'],['ideb2023','IDEB 2023'],['ideb2025','IDEB 2025'],['crescimento','Evolução']]);
    }
  }
  const previousProgress=window.renderSomProgress;
  window.renderSomProgress=function(){
    if(progressActive())return renderCreProgress();
    byId('somProgressChart')?.classList.remove('v181-cre-progress');
    return typeof previousProgress==='function'?previousProgress():undefined;
  };

  function ensureDrawer() {
    let drawer=byId('v181IdebSchoolDrawer');if(drawer)return drawer;
    const backdrop=document.createElement('div');backdrop.id='v181IdebSchoolBackdrop';backdrop.className='v181-school-backdrop';
    drawer=document.createElement('aside');drawer.id='v181IdebSchoolDrawer';drawer.className='v181-school-drawer';drawer.setAttribute('aria-hidden','true');
    drawer.innerHTML=`<div class="v181-school-head"><small id="v181SchoolEyebrow">IDEB</small><h3 id="v181SchoolTitle">Escolas</h3><p id="v181SchoolSubtitle"></p><button type="button" class="v181-school-close" aria-label="Fechar">×</button></div><div class="v181-school-toolbar"><input id="v181SchoolSearch" class="v181-school-search" placeholder="Buscar escola ou agente..." autocomplete="off"></div><div class="v181-school-list" id="v181SchoolList"></div>`;
    document.body.append(backdrop,drawer);
    const close=()=>{drawer.classList.remove('open');backdrop.classList.remove('open');drawer.setAttribute('aria-hidden','true');document.body.classList.remove('v181-school-open');};
    backdrop.addEventListener('click',close);drawer.querySelector('.v181-school-close')?.addEventListener('click',close);
    document.addEventListener('keydown',event=>{if(event.key==='Escape'&&drawer.classList.contains('open'))close();});
    return drawer;
  }
  let drawerItems=[];
  function drawerMetric() {return metric()==='ideb2023'?'ideb2023':'ideb2025';}
  function renderDrawerList(query='') {
    const list=byId('v181SchoolList');if(!list)return;
    const q=String(query||'').trim().toLocaleLowerCase('pt-BR');
    const items=q?drawerItems.filter(item=>`${item.escola} ${item.agent} ${item.cre}`.toLocaleLowerCase('pt-BR').includes(q)):drawerItems;
    if(!items.length){list.innerHTML='<div class="som-empty">Nenhuma escola encontrada neste recorte.</div>';return;}
    list.innerHTML=items.map((item,index)=>{
      const cls=item.delta>0.0001?'up':item.delta<-0.0001?'down':'flat';
      return `<article class="v181-school-item"><div class="v181-school-rank">${index+1}º</div><div class="v181-school-name"><strong>${typeof esc==='function'?esc(item.escola):item.escola}</strong><span>${item.cre} · ${typeof esc==='function'?esc(item.agent||'Agente não informado'):item.agent}</span></div><div class="v181-school-score">${fmt(item.sortValue)}</div><div class="v181-school-evolution"><span><b>2023</b> ${Number.isFinite(item.v23)?fmt(item.v23):'—'}</span><span>→</span><span><b>2025</b> ${Number.isFinite(item.v25)?fmt(item.v25):'—'}</span>${Number.isFinite(item.delta)?`<span class="${cls}">${fmtDelta(item.delta)}</span>`:''}</div></article>`;
    }).join('');
  }
  function openSchoolDrawer() {
    if(!isIdeb())return;
    const drawer=ensureDrawer(),key=drawerMetric(),rows=currentIdebRows().filter(row=>row?.escola&&!row?._afCreAggregate);
    const map=new Map();
    rows.forEach(row=>{
      const id=String(row.codigoSME||row.codigoINEP||`${row.cre}|${row.escola}`),v23=Number(row.ideb2023),v25=Number(row.ideb2025),sortValue=Number(row[key]);
      if(!Number.isFinite(sortValue))return;
      const item={id,escola:String(row.escola||'Escola'),cre:row.cre||row.regional||'—',agent:typeof somRowAgent==='function'?somRowAgent(row):(row.agente||''),v23,v25,delta:Number.isFinite(v23)&&Number.isFinite(v25)?v25-v23:NaN,sortValue};
      const old=map.get(id);if(!old||item.sortValue>old.sortValue)map.set(id,item);
    });
    drawerItems=[...map.values()].sort((a,b)=>b.sortValue-a.sortValue||String(a.escola).localeCompare(String(b.escola),'pt-BR'));
    const scopeText=scope()?`${scope()}ª CRE`:'Toda a SME',label=key==='ideb2023'?'IDEB 2023':'IDEB 2025';
    byId('v181SchoolEyebrow').textContent=`${scopeText} · ${segment()||'segmento'}`;
    byId('v181SchoolTitle').textContent=`Escolas — ${label}`;
    byId('v181SchoolSubtitle').textContent=`${drawerItems.length.toLocaleString('pt-BR')} escolas com resultado válido, ordenadas do maior para o menor ${label}.`;
    const search=byId('v181SchoolSearch');if(search){search.value='';search.oninput=()=>renderDrawerList(search.value);}
    renderDrawerList('');
    drawer.classList.add('open');byId('v181IdebSchoolBackdrop')?.classList.add('open');drawer.setAttribute('aria-hidden','false');document.body.classList.add('v181-school-open');
    setTimeout(()=>drawer.querySelector('.v181-school-close')?.focus(),50);
  }
  function ensureButton() {
    const controls=document.querySelector('#somFiltersCard .som-controls');if(!controls)return;
    let btn=byId('v181ViewIdebSchools');
    if(!btn){
      btn=document.createElement('button');btn.type='button';btn.id='v181ViewIdebSchools';btn.className='v181-view-schools';btn.textContent='Visualizar as escolas';btn.addEventListener('click',openSchoolDrawer);
      const search=byId('somSearch');if(search&&search.parentElement===controls)controls.insertBefore(btn,search);else controls.appendChild(btn);
    }
    btn.hidden=!isIdeb();
  }
  function updateLayout() {
    ensureButton();
    const compareCard=byId('somCreCompareCard'),compareGrid=compareCard?.parentElement,distributionCard=byId('somPie')?.closest('.card');
    const mainCard=byId('somMainChart')?.closest('.card'),mainGrid=mainCard?.parentElement;
    if(pureSme()){
      if(progressActive()){
        if(compareGrid)compareGrid.style.display='none';
        if(mainGrid)mainGrid.style.display='none';
      }else if(['ideb2023','ideb2025'].includes(metric())){
        if(compareGrid){compareGrid.style.display='grid';compareGrid.style.gridTemplateColumns='1fr';}
        if(compareCard){compareCard.style.display='block';compareCard.style.gridColumn='1/-1';}
        if(distributionCard)distributionCard.style.display='none';
        if(mainGrid)mainGrid.style.display='none';
      }
    }else{
      if(compareGrid){compareGrid.style.removeProperty('display');compareGrid.style.removeProperty('grid-template-columns');}
      if(compareCard)compareCard.style.removeProperty('grid-column');
      if(distributionCard)distributionCard.style.removeProperty('display');
      if(mainGrid)mainGrid.style.removeProperty('display');
    }
    if(!pureSme()||(!progressActive()&&!['ideb2023','ideb2025'].includes(metric()))){
      if(distributionCard)distributionCard.style.removeProperty('display');
      if(mainGrid)mainGrid.style.removeProperty('display');
    }
  }

  const previousRender=window.renderResultados;
  window.renderResultados=function(){
    const result=typeof previousRender==='function'?previousRender():undefined;
    setTimeout(updateLayout,0);return result;
  };

  function install(){
    ensureButton();
    ['regionalScopeSelect','somMode','somModalidade','somAnoEscolar','somComponente','somEdicao','somMetric','somAgente','somPriority'].forEach(id=>byId(id)?.addEventListener('change',()=>setTimeout(updateLayout,0)));
    byId('somSearch')?.addEventListener('input',()=>setTimeout(updateLayout,0));
    if(typeof window.renderResultados==='function')window.renderResultados();
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(install,650),{once:true});else setTimeout(install,650);
})();
